import os
import requests

def fetch_recent_logs(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("MIXPANEL_PROJECT_SECRET")
    if not api_key:
        raise ValueError("Missing Mixpanel API key; set config['api_key'] or MIXPANEL_PROJECT_SECRET")

    host = config.get("host") or "https://data.mixpanel.com"
    endpoint = f"{host.rstrip('/')}/api/2.0/export/"
    timeout = config.get("timeout", 30)

    query = {}
    if "from_date" in payload:
        query["from_date"] = payload["from_date"]
    if "to_date" in payload:
        query["to_date"] = payload["to_date"]
    if "where" in payload:
        query["where"] = payload["where"]

    if "filter" in payload and isinstance(payload["filter"], dict):
        clauses = []
        for field, value in payload["filter"].items():
            if isinstance(value, str):
                clauses.append(f'properties["{field}"] == "{value}"')
            else:
                clauses.append(f'properties["{field}"] == {value}')
        filter_expr = " and ".join(clauses)
        if query.get("where"):
            query["where"] = f"({query['where']}) and ({filter_expr})"
        else:
            query["where"] = filter_expr

    result = requests.get(endpoint, params=query, auth=(api_key, ""))
    result.raise_for_status()
    return result.json()
